namespace PaymentGateway.Api.Tests.Unit.Architecture;

/// <summary>
/// <c>docs/how-it-works.html</c> is a standalone copy of <c>docs/how-it-works.md</c> that opens in any browser (GitHub only
/// shows an HTML file's source). It is generated by <c>scripts/build-how-it-works-html.ps1</c>, so this keeps the two in step:
/// edit the Markdown, then run the script.
/// </summary>
public class HowItWorksPageTests
{
    private static string RepositoryRoot()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null && !File.Exists(Path.Combine(directory.FullName, "PaymentGateway.sln")))
        {
            directory = directory.Parent;
        }

        return directory?.FullName ?? throw new InvalidOperationException("The repository root (PaymentGateway.sln) was not found.");
    }

    private static string Normalised(string text) => text.Replace("\r\n", "\n").Trim();

    [Fact]
    public void TheHtmlPage_ExistsAndEmbedsTheCurrentMarkdownVerbatim()
    {
        // Arrange
        var docs = Path.Combine(RepositoryRoot(), "docs");
        var markdown = Normalised(File.ReadAllText(Path.Combine(docs, "how-it-works.md")));
        var htmlPath = Path.Combine(docs, "how-it-works.html");

        // Act
        var html = File.Exists(htmlPath) ? Normalised(File.ReadAllText(htmlPath)) : string.Empty;

        // Assert
        html.Should().Contain(markdown, "docs/how-it-works.html is out of date: run scripts/build-how-it-works-html.ps1");
    }

    [Fact]
    public void TheHtmlPage_LoadsPinnedScriptVersions_NeverALatestTag()
    {
        // Arrange
        var htmlPath = Path.Combine(RepositoryRoot(), "docs", "how-it-works.html");

        // Act
        var html = File.Exists(htmlPath) ? File.ReadAllText(htmlPath) : string.Empty;

        // Assert
        html.Should().MatchRegex(@"marked@\d+\.\d+\.\d+/").And.MatchRegex(@"mermaid@\d+\.\d+\.\d+/");
    }
}